**Idea:** Instead of estimating a “damage deficit”, this policy looks at the *time‑to‑death* of every pirate after the next round. If a pirate would survive to position 2 (one step away from losing) we give the action a huge penalty unless the action kills that pirate this round. For all other pirates we use a simple weighted‑HP score (HP × remaining steps). The action with the smallest (penalty, weighted‑HP, –total‑damage) is chosen, preferring spawns over moves and lower column numbers. This focuses on guaranteeing survival first, then on reducing overall work, which is a different heuristic from the previous “deficit”‑based approaches.  

```python
NUM_COLUMNS = 5
MAX_POSITION = 3          # reaching this loses the game
BIG_PENALTY = 10 ** 6     # enough to dominate any other term


class Policy:
    name = "time_to_death_heuristic"

    # ------------------------------------------------------------------ #
    def choose_action(self, engine):
        # ----- snapshot of current state -----
        cannons = {c: engine.cannons[c].damage for c in engine.cannons}
        pirates = [
            {"column": p.column, "position": p.position, "hp": p.hp}
            for p in engine.pirates
        ]

        # ----- helpers -------------------------------------------------
        def apply_action(cann_map, act):
            """Return a new cannon map after performing act (spawn or move)."""
            new = dict(cann_map)
            if act[0] == "spawn":
                col = act[1]
                new[col] = new.get(col, 0) + 1          # base damage of new cannon
            else:  # move
                donor, target = act[1], act[2]
                dmg = new.pop(donor)                     # donor disappears
                new[target] = new.get(target, 0) + dmg   # damage stacks
                # pending spawn cannon is lost – nothing else to do
            return new

        def simulate_one_round(cann_map, pir_list):
            """Run damage then advance for a single round."""
            pir = [dict(p) for p in pir_list]

            # damage – only the front pirate in each column is hit
            for col, dmg in cann_map.items():
                if dmg <= 0:
                    continue
                col_p = [p for p in pir if p["column"] == col]
                if not col_p:
                    continue
                front = max(col_p, key=lambda p: p["position"])
                front["hp"] -= dmg
                if front["hp"] <= 0:
                    pir.remove(front)

            # advance
            for p in pir:
                p["position"] += 1

            loss = any(p["position"] >= MAX_POSITION for p in pir)
            return pir, loss, cann_map

        def evaluate(pir_list, cann_map):
            """
            Return a tuple (penalty, weighted_hp, -total_damage) for comparison.
            penalty is BIG_PENALTY if any pirate would be at position 2 after
            this round (i.e., one step from loss) and still alive.
            """
            penalty = 0
            weighted_hp = 0
            for p in pir_list:
                steps_left = MAX_POSITION - p["position"]
                if steps_left <= 0:
                    # already lost – should never happen here
                    penalty += BIG_PENALTY
                elif steps_left == 1:
                    # pirate will be at position 2 after this round;
                    # if it survives the next advance we lose → huge penalty
                    penalty += BIG_PENALTY
                weighted_hp += p["hp"] * steps_left

            total_damage = sum(cann_map.values())
            return (penalty, weighted_hp, -total_damage)

        # ----- enumerate all legal first actions -----
        actions = []

        # spawn actions (including merges)
        for col in range(NUM_COLUMNS):
            actions.append(("spawn", col))

        # move actions (donor != target, donor must have a cannon)
        for donor in cannons:
            for target in range(NUM_COLUMNS):
                if donor == target:
                    continue
                actions.append(("move", donor, target))

        best_action = None
        best_score = None

        for act in actions:
            # simulate the round that results from taking this action
            cann_after, loss, _ = simulate_one_round(apply_action(cannons, act), pirates)
            if loss:
                continue    # unsafe action, discard

            # evaluate the resulting state
            score = evaluate(cann_after, apply_action(cannons, act))

            # deterministic tie‑breakers: prefer spawn over move,
            # then lower column numbers (lexicographic on the action tuple)
            tie = (0 if act[0] == "spawn" else 1, act)
            full_score = score + tie  # tuple concatenation works for comparison

            if best_score is None or full_score < best_score:
                best_score = full_score
                best_action = act

        # ----- fallback (should never happen) -----
        if best_action is None:
            # just spawn in any empty column
            for col in range(NUM_COLUMNS):
                if col not in engine.cannons:
                    return ("spawn", col)
            return ("spawn", 0)

        return best_action
```

**Change summary**  
The champion only looks at *spawn* actions for the second round, ignoring that a *move* (which keeps the pending‑spawn cannon for the next round) can sometimes be the only safe way to protect a column where a pirate is about to reach position 3. I extend the two‑step look‑ahead so the second‑round simulation also evaluates every legal move (in addition to every spawn) and picks the one with the smallest deficit. This fixes cases where spawning would immediately lose while moving the existing high‑damage cannon would survive.

